------------------------------------------------------------------------
-- IDENTITY SPOOF MODULE (injected into Misc tab)
------------------------------------------------------------------------
task.spawn(function()
    local sharedEnv = getgenv and getgenv() or _G
    local Players = cloneref(game:GetService(XlOO0l1IIOo))
    local LocalPlayer = Players.LocalPlayer

    -- Wait for Library to be ready
    local lib
    for i = 1, 100 do
        lib = rawget(sharedEnv, z0Il0IlOIl1)
        if lib and lib.Window then break end
        task.wait(0.1)
    end
    if not lib or not lib.Window then return end

    -- Find the Misc tab
    local miscTab
    for name, tab in pairs(lib.Window.Tabs) do
        if tostring(name):lower() == YlOOlOlOIII then
            miscTab = tab
            break
        end
    end
    if not miscTab then return end

    local Options = rawget(sharedEnv, WOlIlOIlol1) or {}
    local Toggles = rawget(sharedEnv, BOlI1lI00lO) or {}

    -- === ACCENT GLOW EFFECT (adjustable neon glow on accent-colored UI) ===
    local glowGroup = miscTab:AddRightGroupbox(tOllOOO0ll1)
    glowGroup:AddToggle(dl1llOOOOI1, { Text = F0I0l0lolO0, Default = true })
    glowGroup:AddSlider(eIlIlllo1lO, {
        Text = oOII1ollloI, Default = 2, Min = 0, Max = 8, Rounding = 1, Suffix = ylOOI1Iooll,
    })
    glowGroup:AddSlider(Kl0lOlIoI0l, {
        Text = jlllI0oI11I, Default = 0.5, Min = 0, Max = 1, Rounding = 2,
    })

    task.spawn(function()
        task.wait(1)
        pcall(function()
            if not lib.ScreenGui then return end
            local defaultAccent = Color3.fromHex(h0I1Io11llO)

            local function colorsMatch(c1, c2)
                if not c1 or not c2 then return false end
                return math.abs(c1.R - c2.R) < 0.12 and math.abs(c1.G - c2.G) < 0.12 and math.abs(c1.B - c2.B) < 0.12
            end

            -- Cache of elements we've attached a glow stroke to
            local tracked = setmetatable({}, { __mode = BI0lIol0OOl })

            local function tryAttach(obj)
                if tracked[obj] then return end
                if not (obj:IsA(S1I0lOIloII) or obj:IsA(ZOol0OIIl0l) or obj:IsA(cOIO0lIOI1O) or obj:IsA(w1oI1OOlI10)) then return end
                if obj.BackgroundTransparency >= 0.9 then return end
                local accent = lib.AccentColor or defaultAccent
                if not colorsMatch(obj.BackgroundColor3, accent) then return end
                local stroke = Instance.new(YloIl0lI0lI)
                stroke.Name = hIO0IO0lIOl
                stroke.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
                stroke.LineJoinMode = Enum.LineJoinMode.Round
                stroke.Color = accent
                stroke.Thickness = 2
                stroke.Transparency = 0.5
                stroke.Enabled = true
                stroke.Parent = obj
                tracked[obj] = stroke
            end

            local function applySettings()
                local Tog = rawget(sharedEnv, 'TogglesNlI0olIlOIIOptions') or {}
                local enabled = true
