                local candidates = {
                    {RS:FindFirstChild(COollo1I1Ol), ul1IIlIooll},
                    {RS:FindFirstChild(VIllOO0ol1O), pIl110O1Ill},
                    {RS:FindFirstChild(cIl10IIlOol), UO1O1lIOIlO},
                    {RS:FindFirstChild(n0OlI1IO0Io), W0lOOOlllIO},
                    {RS:FindFirstChild(P1O0o0llI1l), plIIllI10Il},
                    {RS:FindFirstChild(PIOllOIIIl0), v0IOoOI0olO},
                    {RS:FindFirstChild(QI1110Ilo0I), PI11lO0olI0},
