    -- === SPOOF ENGINE ===
    local rawget = rawget
    local rawset = rawset
    local pcall = pcall

    local function safeCall(fn, ...)
        local ok, err = pcall(fn, ...)
        if not ok then warn(k1O1llI1lo0, err) end
        return ok
    end

    -- Attribute guard system
    local attrGuards = {}

    local function guardAttribute(player, attribute)
        local key = tostring(player.UserId) .. dlOOl0OOl1O .. attribute
        if attrGuards[key] then return attrGuards[key] end

        local original = player:GetAttribute(attribute)
        local isWriting = false
        local spoofed = nil

        local conn = player:GetAttributeChangedSignal(attribute):Connect(function()
            if isWriting then return end
            original = player:GetAttribute(attribute)
            if spoofed ~= nil then
                isWriting = true
                player:SetAttribute(attribute, spoofed)
                isWriting = false
            end
        end)

        local guard = {
            Set = function(_, val)
                spoofed = val
                isWriting = true
                player:SetAttribute(attribute, val or original)
                isWriting = false
            end,
            Restore = function(_)
                spoofed = nil
                isWriting = true
                player:SetAttribute(attribute, original)
                isWriting = false
            end,
            Destroy = function(_)
                conn:Disconnect()
                pcall(function() player:SetAttribute(attribute, original) end)
                attrGuards[key] = nil
            end,
        }

        attrGuards[key] = guard
        return guard
    end

    -- Leaderstat spoof system
    local leaderstatEntries = {}

    local function applyLeaderstat(player, path, toggleName, getValueFn)
        local entryKey = tostring(player.UserId) .. qlll1o00IIO .. table.concat(path, iO0OlI01I0I)
        if leaderstatEntries[entryKey] then return end

        task.spawn(function()
            local current = player
            for _, name in ipairs(path) do
                local child = current:FindFirstChild(name)
                if not child then
                    local startT = os.clock()
                    repeat
                        child = current:FindFirstChild(name)
                        if child then break end
                        task.wait(0.1)
                    until child or (os.clock() - startT > 10)
                end
                if not child then return end
                current = child
            end

            local stat = current
            local original = stat.Value
            local isWriting = false

            local conn = stat:GetPropertyChangedSignal(qOllO0I0l01):Connect(function()
                if isWriting then return end
                original = stat.Value
                if Toggles[toggleName] and Toggles[toggleName].Value then
                    isWriting = true
                    stat.Value = getValueFn()
                    isWriting = false
                end
            end)

            leaderstatEntries[entryKey] = {
                Stat = stat,
                Original = original,
                Connection = conn,
            }

            if Toggles[toggleName] and Toggles[toggleName].Value then
                isWriting = true
                stat.Value = getValueFn()
                isWriting = false
            end
        end)
    end

    local function removeLeaderstat(player, path)
        local entryKey = tostring(player.UserId) .. n0Oo0lOllIO .. table.concat(path, e1l1lIlI100)
        local entry = leaderstatEntries[entryKey]
        if entry then
            entry.Connection:Disconnect()
            pcall(function() entry.Stat.Value = entry.Original end)
            leaderstatEntries[entryKey] = nil
        end
    end

    -- Attribute-to-toggle mapping
    local ATTR_MAP = {
        IS_WinstreakSpoof = { attr = BIII11I01lI, getValue = function() return tonumber(Options.IS_WinstreakValue and Options.IS_WinstreakValue.Value) or 50 end },
        IS_LevelSpoof     = { attr = NIlo0IIoIll, getValue = function() return tonumber(Options.IS_LevelValue and Options.IS_LevelValue.Value) or 100 end, leaderstat = {d1oo0OOIIIo, tlIOllIOOoI} },
        IS_EloSpoof       = { attr = sIl0IlIolIl, getValue = function() return tonumber(Options.IS_EloValue and Options.IS_EloValue.Value) or 2000 end, leaderstat = {TI0I1OlI0IO, pII00IIOII1} },
        IS_NametagStatus  = { attr = y1oOOoIOIl0, getValue = function() return Options.IS_NametagType and Options.IS_NametagType.Value or q1Ol00IIO11 end },
        IS_Influencer     = { attr = m1110IOl0oI, getValue = function() return true end },
        IS_RobloxEmployee = { attr = kIlo100lO0l, getValue = function() return true end },
        IS_NosniyTeam     = { attr = dOlOI1O1loI, getValue = function() return 255 end },
    }

    -- Apply one attribute spoof to a player
    local function applySingleSpoof(player, toggleName)
        local info = ATTR_MAP[toggleName]
        if not info then return end
        guardAttribute(player, info.attr):Set(info.getValue())
        if info.leaderstat then
            applyLeaderstat(player, info.leaderstat, toggleName, info.getValue)
        end
    end

    -- Restore one attribute spoof from a player
    local function restoreSingleSpoof(player, toggleName)
        local info = ATTR_MAP[toggleName]
        if not info then return end
        local key = tostring(player.UserId) .. qI0OlOlOI1o .. info.attr
        local guard = attrGuards[key]
        if guard then
            guard:Destroy()
        end
        if info.leaderstat then
            removeLeaderstat(player, info.leaderstat)
        end
    end

    -- Apply all enabled attribute spoofs to LocalPlayer only
    local function applyAllSpoofs()
        for toggleName, _ in pairs(ATTR_MAP) do
            if Toggles[toggleName] and Toggles[toggleName].Value then
                applySingleSpoof(LocalPlayer, toggleName)
            end
        end
    end

    -- Apply on start
    applyAllSpoofs()

    -- Wire up each toggle: ON = apply to self, OFF = restore instantly
    for toggleName, _ in pairs(ATTR_MAP) do
        if Toggles[toggleName] then
            Toggles[toggleName]:OnChanged(function(val)
                if val then
                    safeCall(applySingleSpoof, LocalPlayer, toggleName)
                else
                    safeCall(restoreSingleSpoof, LocalPlayer, toggleName)
                end
            end)
        end
    end

    -- Slider/dropdown change callbacks to re-apply active spoofs (self only)
    local function reapplyToggle(toggleName)
        if Toggles[toggleName] and Toggles[toggleName].Value then
            safeCall(applySingleSpoof, LocalPlayer, toggleName)
        end
    end

    if Options.IS_WinstreakValue then Options.IS_WinstreakValue:OnChanged(function() reapplyToggle('IS_WinstreakSpoofsO0IlIlIOOOIS_LevelSpoofWO0IlO00llIIS_EloSpoofYI1oOllOoOlIS_NametagStatus') end) end


    -- === THUMBNAIL SPOOF (replace avatar icon in GUI) ===
    local RunService = game:GetService(gI0II0Ol0Il)
    local thumbConns = {}
    local thumbSpoofActive = false
    local myIdStr = tostring(LocalPlayer.UserId)

    local function replaceThumbIn(obj)
        pcall(function()
            if not (obj:IsA(RIOO1I1I1OO) or obj:IsA(D01IIoOIllI)) then return end
            local img = obj.Image
            if type(img) ~= r1oI1OO0IOl or img == "" then return end
            if string.find(img, myIdStr, 1, true) then
                local sid = tonumber(Options.IS_AvatarUserId and Options.IS_AvatarUserId.Value)
                if sid then
                    obj.Image = string.gsub(img, myIdStr, tostring(sid))
                end
            end
        end)
    end

    local function startThumbSpoof()
        if thumbSpoofActive then return end
        thumbSpoofActive = true

        local playerGui = LocalPlayer:FindFirstChild(V0II0lllIII)
        if not playerGui then return end

        for _, obj in ipairs(playerGui:GetDescendants()) do
            replaceThumbIn(obj)
        end

        thumbConns[1] = playerGui.DescendantAdded:Connect(function(obj)
            replaceThumbIn(obj)
            task.defer(function() replaceThumbIn(obj) end)
        end)

        -- Safety-net rescan for images whose Image property changes after creation.
        -- DescendantAdded above already covers newly created ones, so this can be
        -- infrequent: a full PlayerGui walk is expensive in Rivals.
        local scanClock = 0
        thumbConns[2] = RunService.Heartbeat:Connect(function(dt)
            scanClock = scanClock + dt
            if scanClock < 1 then return end
            scanClock = 0
            pcall(function()
                local sid = tonumber(Options.IS_AvatarUserId and Options.IS_AvatarUserId.Value)
                if not sid then return end
                local s = tostring(sid)
                for _, obj in ipairs(playerGui:GetDescendants()) do
                    if obj:IsA(Col1ooIoI11) or obj:IsA(v1OoOIOlOI0) then
                        local img = obj.Image
                        if type(img) == nOIlO0I00OI and string.find(img, myIdStr, 1, true) then
                            obj.Image = string.gsub(img, myIdStr, s)
                        end
                    end
                end
            end)
        end)
    end

    local function stopThumbSpoof()
        thumbSpoofActive = false
        for _, conn in pairs(thumbConns) do
            if conn then pcall(function() conn:Disconnect() end) end
        end
        thumbConns = {}
    end

    -- Declared here so the toggle handler below can see it; the methods are
    -- filled in further down. A `local function` defined later would not be
    -- visible to this handler, which resolves names at compile time.
    local AvatarSpoof = {}

    if Toggles.IS_AvatarSpoof then
        Toggles.IS_AvatarSpoof:OnChanged(function(val)
            if val then
                task.spawn(startThumbSpoof)
                task.spawn(function()
                    local sid = tonumber(Options.IS_AvatarUserId and Options.IS_AvatarUserId.Value)
                    if not sid then
                        lib:Notify(mlII00IIlOo, 4)
                        return
                    end
                    local char = LocalPlayer.Character
                    for i = 1, 30 do
                        if char then break end
                        task.wait(0.2)
                        char = LocalPlayer.Character
                    end
                    if not char then
                        lib:Notify(vIOIIolOIIl, 4)
                        return
                    end
                    local ok, msg = AvatarSpoof.ApplyToCharacter(char, sid)
                    if ok then
                        lib:Notify(aolIl00Oo10 .. tostring(msg), 3)
                    else
                        lib:Notify(Uolo0oII1I0 .. tostring(msg), 5)
                    end
                    AvatarSpoof.Watch(char)
                end)
            else
                stopThumbSpoof()
                task.spawn(function()
                    local ok, err = pcall(AvatarSpoof.Restore)
                    if ok then
                        lib:Notify(dlllOIIOIIl, 2)
                    else
                        lib:Notify(K1OI0olOOlo .. tostring(err), 4)
                    end
                end)
            end
        end)
    end

    thumbConns[99] = LocalPlayer.CharacterAdded:Connect(function()
        if Toggles.IS_AvatarSpoof and Toggles.IS_AvatarSpoof.Value then
            task.delay(1, function()
                stopThumbSpoof()
                task.spawn(startThumbSpoof)
            end)
        end
    end)

    -- === AVATAR SPOOF (port of KiciaHook standalone AvatarSpoof) ===
    AvatarSpoof._spoofedInstances = {}
    AvatarSpoof._stashed = {}
    AvatarSpoof._applying = false
    AvatarSpoof._pending = false
    AvatarSpoof._watchConn = nil

    function AvatarSpoof._Apply(character, userId)
        local humanoid = character:FindFirstChildOfClass(Ao1oI1O1III)
        if not humanoid then
            local start = os.clock()
            repeat
                humanoid = character:FindFirstChildOfClass(iI0lIoI10Ol)
                task.wait(0.1)
            until humanoid or (os.clock() - start > 10)
        end
        if not humanoid then return false, zlOOIOolI0l end

        local ok, model = pcall(function()
            return Players:CreateHumanoidModelFromDescriptionAsync(
                Players:GetHumanoidDescriptionFromUserId(userId),
                humanoid.RigType
            )
        end)
        if not ok or not model then
            return false, tostring(model)
        end

        local key = character:GetFullName()
        local prevSpoofed = AvatarSpoof._spoofedInstances[key]
        local spoofed = {}
        -- Keep any earlier stash: on a re-apply the genuine originals were
        -- already taken off the character the first time round.
        local stashed = AvatarSpoof._stashed[key] or {}

        for _, child in ipairs(character:GetChildren()) do
            if child:IsA(jIIOOllOl0I) or child:IsA(II0olll1III) or child:IsA(h0OlllOOllI) or child:IsA(tlO0l0lll0o) then
                if prevSpoofed and prevSpoofed[child] then
                    -- ours from a previous apply; drop it rather than stashing it
                    child:Destroy()
                else
                    child.Parent = nil
                    table.insert(stashed, child)
                end
            end
        end

        local copied = 0

        for _, child in ipairs(model:GetChildren()) do
            if child:IsA(xoIlI1IlOOI) then
                child.Parent = nil
                spoofed[child] = true

                local handle = child:FindFirstChild(GO0OOloIO1I)
                if handle and handle:IsA(tI0ll0o0l0I) then
                    for _, w in ipairs(handle:GetChildren()) do
                        if w:IsA(bl1IIlOII00) or w:IsA(g1lI00IooOo) or w:IsA(h00OOI1I0ol) then
                            w:Destroy()
                        end
                    end

                    local att = nil
                    for _, a in ipairs(handle:GetChildren()) do
                        if a:IsA(Clo0OlOI0lo) then att = a; break end
                    end

                    if att then
                        local target = nil
                        for _, part in ipairs(character:GetChildren()) do
                            if part:IsA(mlOlIlI0l1O) then
                                local found = part:FindFirstChild(att.Name)
                                if found and found:IsA(tIloOIoII0l) then
                                    target = found; break
                                end
                            end
                        end

                        if target then
                            handle.Anchored = false
                            local weld = Instance.new(y1lllIlOIOI)
                            weld.Name = CIlOl0II0lO
                            weld.Part0 = handle
                            weld.Part1 = target.Parent
                            weld.C0 = att.CFrame
                            weld.C1 = target.CFrame
                            weld.Parent = handle
                        end
                    end
                end

                child.Parent = character
                copied = copied + 1
            elseif child:IsA(x0oO0l0loII) or child:IsA(E11OO0IllOl) or child:IsA(kIOIlIl11I0) then
                spoofed[child] = true
                child.Parent = character
                copied = copied + 1
            elseif child:IsA(A11000I0l0I) then
                local match = character:FindFirstChild(child.Name)
                if match and match:IsA(DIIOllI1oOO) then
                    match.Color = child.Color
                end
            end
        end

        local srcHead = model:FindFirstChild(ZlOllllIII0)
        local dstHead = character:FindFirstChild(dI1lO0ol10I)
        if srcHead and dstHead and srcHead:IsA(vIIo10I00IO) and dstHead:IsA(J0o0Ol0O0lI) then
            dstHead.Transparency = srcHead.Transparency
            if srcHead:IsA(HlI10lOlII0) and dstHead:IsA(dIoI1lI0IlI) then
                dstHead.MeshId = srcHead.MeshId
                dstHead.TextureID = srcHead.TextureID
            end
        end

        model:Destroy()

        AvatarSpoof._spoofedInstances[key] = spoofed
        AvatarSpoof._stashed[key] = stashed
        return true, uO1IOIOIIII .. copied .. qIIIOlIl0II
    end

    -- Guarded entry point: the watcher below reacts to accessories appearing on
    -- the character, and _Apply adds some itself, so re-entry must be blocked.
    function AvatarSpoof.ApplyToCharacter(character, userId)
        if AvatarSpoof._applying then return false, FllI0O0OIlI end
        AvatarSpoof._applying = true
        local ran, a, b = pcall(AvatarSpoof._Apply, character, userId)
        AvatarSpoof._applying = false
        if not ran then return false, tostring(a) end
        return a, b
    end

    -- Rivals puts the lobby outfit back on the character between rounds, which
    -- wipes the spoof. Watch for that and re-apply. Event-driven, so idle cost
    -- is zero; the debounce lets Rivals finish adding every item first.
    function AvatarSpoof.Watch(character)
        if AvatarSpoof._watchConn then
            pcall(function() AvatarSpoof._watchConn:Disconnect() end)
            AvatarSpoof._watchConn = nil
        end
        if not character then return end

        AvatarSpoof._watchConn = character.ChildAdded:Connect(function(child)
            if AvatarSpoof._applying or AvatarSpoof._pending then return end
            if not (Toggles.IS_AvatarSpoof and Toggles.IS_AvatarSpoof.Value) then return end
            if not (child:IsA(Olll1O0II0O) or child:IsA(plI00lOI001)
                or child:IsA(Fl0ool10lll) or child:IsA(SlIIOO00I00)) then return end

            local set = AvatarSpoof._spoofedInstances[character:GetFullName()]
            if set and set[child] then return end

            AvatarSpoof._pending = true
            task.spawn(function()
                task.wait(0.5)
                AvatarSpoof._pending = false
                if not (Toggles.IS_AvatarSpoof and Toggles.IS_AvatarSpoof.Value) then return end
                local uid = tonumber(Options.IS_AvatarUserId and Options.IS_AvatarUserId.Value)
                local c = LocalPlayer.Character
                if not uid or not c then return end
                local okApply, msg = AvatarSpoof.ApplyToCharacter(c, uid)
                if not okApply then warn(Jll11IIOIlI .. tostring(msg)) end
            end)
        end)
    end

    function AvatarSpoof.Restore()
        local character = LocalPlayer.Character

        if AvatarSpoof._watchConn then
            pcall(function() AvatarSpoof._watchConn:Disconnect() end)
            AvatarSpoof._watchConn = nil
        end

        for _, spoofed in pairs(AvatarSpoof._spoofedInstances) do
            for item in pairs(spoofed) do
                pcall(function() item:Destroy() end)
            end
        end
        AvatarSpoof._spoofedInstances = {}

        for _, stashed in pairs(AvatarSpoof._stashed) do
            for _, item in ipairs(stashed) do
                pcall(function()
                    if character then
                        item.Parent = character
                    else
                        item:Destroy()
                    end
                end)
            end
        end
        AvatarSpoof._stashed = {}
    end

    -- Reapply after respawn, matching the standalone's 1s settle delay
    thumbConns[98] = LocalPlayer.CharacterAdded:Connect(function(char)
        if not (Toggles.IS_AvatarSpoof and Toggles.IS_AvatarSpoof.Value) then return end
        task.spawn(function()
            task.wait(1)
            local userId = tonumber(Options.IS_AvatarUserId and Options.IS_AvatarUserId.Value)
            if not userId then return end
            local okApply, msg = AvatarSpoof.ApplyToCharacter(char, userId)
            if not okApply then
                warn(eOOl0I0OO0O .. tostring(msg))
            end
            AvatarSpoof.Watch(char)
        end)
    end)

    -- === DATA HOOK (Level/ELO/Winstreak on profile card + thumbnail) ===
    pcall(function()
        local mt = getrawmetatable(game)
        if not mt then return end
        local oldNc = mt.__namecall
        if not oldNc then return end
        setreadonly(mt, false)

        mt.__namecall = newcclosure(function(self, ...)
            local ok, method = pcall(getnamecallmethod)
            if not ok then return oldNc(self, ...) end

            if method ~= mol1o01OlOo and method ~= zlI0I1llOOl then
                return oldNc(self, ...)
            end

            if method == V11II1I0IOo then
                if self == Players and Toggles.IS_AvatarSpoof and Toggles.IS_AvatarSpoof.Value then
                    local thumbArgs = {...}
                    local spoofId = tonumber(Options.IS_AvatarUserId and Options.IS_AvatarUserId.Value)
                    if spoofId and thumbArgs[1] == LocalPlayer.UserId then
                        thumbArgs[1] = spoofId
                        return oldNc(self, unpack(thumbArgs))
                    end
                end
                return oldNc(self, ...)
            end

            local results = table.pack(oldNc(self, ...))

            local isRemFunc = false
            pcall(function() isRemFunc = self:IsA(tIlI0o1l01l) end)
            if isRemFunc and type(results[1]) == Fl0110O0ll0 then
                pcall(function()
                    local seen = {}
                    local function tryPatch(t)
                        if type(t) ~= ZIIoIlllIIO or seen[t] then return end
                        seen[t] = true
                        local hasLevel = t.Level ~= nil and type(t.Level) == gOlI0O0OlIl
                        local hasELO = t.DisplayELO ~= nil and type(t.DisplayELO) == WIlO001lOll
                        local hasStreak = t.StatisticDuelsWinStreak ~= nil and type(t.StatisticDuelsWinStreak) == ZIl1O0OI00I
                        if hasLevel or hasELO or hasStreak then
                            if hasLevel and Toggles.IS_LevelSpoof and Toggles.IS_LevelSpoof.Value then
                                t.Level = tonumber(Options.IS_LevelValue and Options.IS_LevelValue.Value) or 100
                            end
                            if hasELO and Toggles.IS_EloSpoof and Toggles.IS_EloSpoof.Value then
                                t.DisplayELO = tonumber(Options.IS_EloValue and Options.IS_EloValue.Value) or 2000
                            end
                            if hasStreak and Toggles.IS_WinstreakSpoof and Toggles.IS_WinstreakSpoof.Value then
                                t.StatisticDuelsWinStreak = tonumber(Options.IS_WinstreakValue and Options.IS_WinstreakValue.Value) or 50
                            end
                        end
                        for _, v in pairs(t) do
                            if type(v) == IOlOoo0I0lI then pcall(tryPatch, v) end
                        end
                    end
                    pcall(tryPatch, results[1])
                end)
            end

            return table.unpack(results, 1, results.n)
        end)

        setreadonly(mt, true)
    end)

    -- Ping spoof
    local PING_RANGES = {
        Low    = {150, 160},
        Medium = {60, 75},
        High   = {17, 25},
    }
    local pingRestore = nil

    if Toggles.IS_PingSpoof then
        Toggles.IS_PingSpoof:OnChanged(function(val)
            if val then
                pcall(function()
                    for _, module in pairs(game:GetService(z00IlOOOOlo):GetDescendants()) do
                        if module:IsA(UOOl0IOO1ll) then
                            local success, loaded = pcall(require, module)
                            if success and type(loaded) == VOOIIlOlolI and loaded.Utility then
                                local utility = loaded.Utility
                                local mt = getmetatable(utility)
                                if not mt then return end
                                local idx = rawget(mt, BO0l1OIIOOO)
                                if type(idx) ~= cO1lIIO0Ill then return end
                                local original = rawget(idx, QoOllIlI1Oo)
                                if type(original) ~= SlOOlO0OI0I then return end

                                local upIdx, origPlayers
                                for k, v in debug.getupvalues(original) do
                                    if typeof(v) == s0OIOlOllII and v:IsA(Ql1I1OII00l) then
                                        upIdx = k
                                        origPlayers = v
                                        break
                                    end
                                end
                                if not upIdx then return end

                                local pingType = Options.IS_PingType and Options.IS_PingType.Value or sOIIOIo10II
                                local range = PING_RANGES[pingType] or PING_RANGES.Low

                                debug.setupvalue(original, upIdx, {
                                    LocalPlayer = {
                                        GetNetworkPing = function()
                                            return math.random(range[1], range[2]) / 1000
                                        end,
                                    },
                                })

                                pingRestore = {Fn = original, Index = upIdx, Original = origPlayers}
                                break
                            end
                        end
                    end
                end)
            elseif pingRestore then
                debug.setupvalue(pingRestore.Fn, pingRestore.Index, pingRestore.Original)
                pingRestore = nil
            end
        end)
    end

    -- Re-trigger autoload now that IS_ toggles/inputs exist
    task.spawn(function()
        task.wait(0.5)
        pcall(function()
            local sm = getgenv().SaveManager
            if sm and sm.LoadAutoloadConfig then
                sm:LoadAutoloadConfig()
            end
        end)
    end)
end)

return _result
